window.EP = {"name": "ch8", "label": "एपिसोड 8", "en": "Who Brought the Greeks to Skeleton Lake?", "duration": 1127.69, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 14.86, "text": "चैप्टर एट। हू ब्रॉट द ग्रीक्स टू स्केलेटन लेक?"}, {"start": 15.41, "end": 19.83, "text": "डेज़ एट टू नाइन। वान एंड रूपकुंड"}], "captions": [{"start": 21.38, "end": 24.93, "text": "जोशीमठ वापस पहुँचकर, मैंने सबसे पहला काम ये किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 24.93, "end": 26.89, "text": "कि अपनी मम्मी को फ़ोन किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 27.34, "end": 28.52, "text": "मम्मी, एक काम करो।", "who": "", "voice": "narrator", "diary": false}, {"start": 28.52, "end": 30.62, "text": "एक हफ़्ते के लिए वडोदरा चली जाओ।", "who": "", "voice": "narrator", "diary": false}, {"start": 30.62, "end": 31.34, "text": "मौसी के घर।", "who": "", "voice": "narrator", "diary": false}, {"start": 31.79, "end": 32.54, "text": "ख़ामोशी।", "who": "", "voice": "narrator", "diary": false}, {"start": 32.54, "end": 35.37, "text": "फिर, उस जानलेवा सटीकता के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 35.37, "end": 39.7, "text": "जो आज तक की हर हिंदुस्तानी माँ के पास होती है:", "who": "", "voice": "narrator", "diary": false}, {"start": 40.15, "end": 41.43, "text": "भूत के पीछे पड़े हो ना?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 41.88, "end": 42.28, "text": "मम्मी…", "who": "", "voice": "narrator", "diary": false}, {"start": 42.73, "end": 44.31, "text": "मैंने कहा था।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 44.31, "end": 46.25, "text": "पहले दिन कहा था।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 46.45, "end": 47.25, "text": "एक पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 47.45, "end": 48.24, "text": "स्वेटर पहना?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 48.69, "end": 49.32, "text": "तीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 49.77, "end": 50.31, "text": "ठीक है।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 50.31, "end": 51.17, "text": "जा रही हूँ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 51.17, "end": 54.13, "text": "मौसी को बता देना, तुम कितने बुद्धू हो।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 54.33, "end": 55.44, "text": "एक और पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 55.44, "end": 56.77, "text": "फिर, धीरे से:", "who": "", "voice": "narrator", "diary": false}, {"start": 56.97, "end": 57.58, "text": "पार्थ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 57.58, "end": 58.72, "text": "ध्यान रखना।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 59.17, "end": 60.5, "text": "मैं बताना चाहूँगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 60.5, "end": 63.97, "text": "कि इस पूरी बातचीत के दौरान मैं बिल्कुल शांत था।", "who": "", "voice": "narrator", "diary": false}, {"start": 63.97, "end": 68.62, "text": "शाओनी, जो दूसरे बेड पर बैठी सब सुन रही थी, कुछ और बताना चाहेगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 68.62, "end": 71.72, "text": "हमने तय किया है, कि इस पर बात नहीं करेंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 73.22, "end": 75.42, "text": "फिर क्षितिज को प्रॉब्लम मिली।", "who": "", "voice": "narrator", "diary": false}, {"start": 75.87, "end": 79.68, "text": "वो मेरे लैपटॉप के साथ, ज़मीन पर पालथी मारे बैठा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 79.68, "end": 83.72, "text": "और सवॉय में रोहन की नोटबुक की जो फ़ोटोज़ मैंने ली थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 83.72, "end": 85.06, "text": "उन्हें देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 85.06, "end": 89.77, "text": "हर पेज, यूनिट फ़ोर प्रैक्टिकल मार्क्स नाम के फ़ोल्डर में बैकअप।", "who": "", "voice": "narrator", "diary": false}, {"start": 89.77, "end": 92.46, "text": "ढूँढ रहा था, कि कुछ छूट तो नहीं गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 92.46, "end": 97.25, "text": "अचानक उसने स्क्रॉल करना बंद किया, और स्क्रीन हमारी तरफ़ घुमा दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 97.7, "end": 102.28, "text": "पीछे के एक पेज पर, कटे हुए गाँवों के नामों की एक लिस्ट में,", "who": "", "voice": "narrator", "diary": false}, {"start": 102.28, "end": 106.39, "text": "एक लाइन थी, जिसे हम सबने सरसरी नज़र में छोड़ दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 106.84, "end": 107.32, "text": "वान।", "who": "", "voice": "narrator", "diary": false}, {"start": 107.32, "end": 108.5, "text": "भवान सिंह।", "who": "", "voice": "narrator", "diary": false}, {"start": 108.5, "end": 109.1, "text": "पोता?", "who": "", "voice": "narrator", "diary": false}, {"start": 109.1, "end": 109.93, "text": "पोर्टर।", "who": "", "voice": "narrator", "diary": false}, {"start": 109.93, "end": 110.4, "text": "चेक।", "who": "", "voice": "narrator", "diary": false}, {"start": 110.85, "end": 111.65, "text": "भवान सिंह।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 111.85, "end": 112.71, "text": "क्षितिज ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 112.91, "end": 114.45, "text": "बही में तीसरा नाम।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 114.45, "end": 117.88, "text": "प्रताप सिंह रावत, भवान सिंह, कुंदन सिंह।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 118.33, "end": 122.33, "text": "वान, रूपकुंड के ट्रेल से पहले का आख़िरी गाँव है।", "who": "", "voice": "narrator", "diary": false}, {"start": 122.78, "end": 124.84, "text": "मुझे लगा, ज़मीन झुक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 125.04, "end": 127.26, "text": "तो हमने उसे जो झूठा वर्स दिया…", "who": "", "voice": "narrator", "diary": false}, {"start": 127.71, "end": 129.91, "text": "उसने उसे बिल्कुल सही जगह भेज दिया।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 130.11, "end": 134.93, "text": "शाओनी ने मेरा वाक्य मेरे लिए, सख़्ती से पूरा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 135.13, "end": 139.51, "text": "मुर्दों की झील के रास्ते में एक असली आदमी बैठा है,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 139.51, "end": 144.06, "text": "जिसके दादा ने उन्नीस सौ छियासठ में गरम शिला देखी थी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 144.06, "end": 149.49, "text": "और रोहन वहाँ जा रहा है, ये सोचके, कि गीत उसे वहाँ बुला रहा है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 149.94, "end": 154.93, "text": "हमने एक भेड़िये को ख़ाली मैदान में भेजने की कोशिश की थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 154.93, "end": 158.58, "text": "हमने उसे सीधा एक भेड़ के पास भेज दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 159.03, "end": 161.56, "text": "क्षितिज का चेहरा सफ़ेद पड़ गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 161.56, "end": 165.72, "text": "वो स्क्रीन को ऐसे घूर रहा था, जैसे उसने उसे काट लिया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 166.17, "end": 167.06, "text": "मेरी ग़लती है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 167.26, "end": 167.9, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 168.1, "end": 169.24, "text": "मैंने वर्स लिखा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 169.24, "end": 171.52, "text": "मैंने नोटबुक ध्यान से नहीं पढ़ी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 171.52, "end": 173.73, "text": "मैं क्लू फ़ाइंडर हूँ, और मैंने…", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 174.18, "end": 174.71, "text": "हमारी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 174.91, "end": 175.77, "text": "शाओनी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 176.22, "end": 177.65, "text": "दीदी, मैंने…", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 178.1, "end": 179.22, "text": "प्लान मेरा था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 179.22, "end": 180.35, "text": "वर्स तुम्हारा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 180.35, "end": 182.12, "text": "नोटबुक पार्थ ने चुराई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 182.12, "end": 184.38, "text": "गाड़ी गब्बर भैया चला रहे थे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 184.58, "end": 189.86, "text": "उसने अपनी उँगलियों पर गिनाया, पूरे वक़्त अपने भाई को देखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 190.06, "end": 192.55, "text": "ग़लती सबकी है, तो ग़लती किसी की नहीं है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 192.55, "end": 192.92, "text": "लॉजिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 193.12, "end": 194.39, "text": "उसने अपना बैग उठाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 194.59, "end": 195.07, "text": "अब चलो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 195.07, "end": 196.77, "text": "रोना है, तो वान पहुँच के।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 197.22, "end": 199.33, "text": "ज़ाहिर है, वो लॉजिक नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 199.33, "end": 200.31, "text": "वो एक बहन थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 200.31, "end": 202.26, "text": "लेकिन क्षितिज खड़ा हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.71, "end": 205.11, "text": "गब्बर पहले ही बसंती को स्टार्ट कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 206.61, "end": 219.77, "text": "जोशीमठ से वान तक लंबी ड्राइव है: नीचे कर्णप्रयाग तक, फिर पिंडर घाटी में ऊपर, ऐसे गाँवों से होते हुए, जो पहाड़ियों से सूखते कपड़ों की तरह लटके हुए हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 219.77, "end": 224.42, "text": "और आख़िर में, एक पतली सड़क से ऊपर, जंगल के किनारे पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 224.42, "end": 228.72, "text": "स्लेट की छतों और अखरोट के पेड़ों वाले एक गाँव तक।", "who": "", "voice": "narrator", "diary": false}, {"start": 228.72, "end": 231.43, "text": "हमने लगभग पूरी रात ड्राइव किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 231.88, "end": 234.55, "text": "भवान सिंह के पोते का नाम हीरा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 234.55, "end": 237.06, "text": "चालीस के आसपास, दुबला, कसा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 237.06, "end": 241.99, "text": "ऊँचाई की धूप से जला हुआ गहरा चेहरा, और पुरानी रस्सी जैसे हाथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 241.99, "end": 246.2, "text": "वो पंद्रह साल की उम्र से रूपकुंड ट्रेल पर पोर्टर था।", "who": "", "voice": "narrator", "diary": false}, {"start": 246.65, "end": 247.79, "text": "और दो दिन पहले,", "who": "", "voice": "narrator", "diary": false}, {"start": 247.79, "end": 251.68, "text": "उसे समिट सीक्रेट्स नाम की एक कंपनी ने हायर किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 252.13, "end": 257.72, "text": "उसने हमें ये, भोर में, अपनी दहलीज़ पर, चाय का कप लिए बैठे हुए बताया,", "who": "", "voice": "narrator", "diary": false}, {"start": 257.72, "end": 261.17, "text": "हम में से किसी की तरफ़ पूरी तरह देखे बिना।", "who": "", "voice": "narrator", "diary": false}, {"start": 261.62, "end": 263.08, "text": "बहुत पैसा दे रहे हैं।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 263.08, "end": 264.61, "text": "सीज़न ख़त्म हो गया है।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 264.61, "end": 266.9, "text": "इतनी बर्फ़ में कोई ऊपर नहीं जाता।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 266.9, "end": 268.63, "text": "पर ये लोग जाना चाहते हैं।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 268.63, "end": 270.23, "text": "कहते हैं, कोई सर्वे है।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 270.23, "end": 271.62, "text": "आज सुबह का प्लान था।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 271.62, "end": 274.82, "text": "फिर उन्होंने कहा, रुक जाओ, साब ख़ुद आ रहे हैं।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 275.27, "end": 277.59, "text": "शाओनी उसके नीचे वाली सीढ़ी पर बैठ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 277.79, "end": 278.25, "text": "हीरा जी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 278.45, "end": 280.11, "text": "उसने सावधानी से पूछा,", "who": "", "voice": "narrator", "diary": false}, {"start": 280.31, "end": 284.7, "text": "आपके दादा ने कभी, एक गरम पत्थर के बारे में बात की थी?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 285.15, "end": 287.18, "text": "तब हीरा ने ऊपर देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.18, "end": 289.93, "text": "सच में हमें देखा, पहली बार।", "who": "", "voice": "narrator", "diary": false}, {"start": 290.38, "end": 291.61, "text": "आप लोगों को कैसे पता?", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 292.06, "end": 293.43, "text": "हमने उसे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 293.43, "end": 294.53, "text": "सब कुछ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 294.53, "end": 295.08, "text": "काफ़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 295.53, "end": 298.67, "text": "वो सुनता रहा, अपना कप गोल-गोल घुमाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 298.67, "end": 302.81, "text": "फिर उसने कुछ ऐसा कहा, जिसने पूरी कहानी की शक्ल बदल दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 303.26, "end": 306.52, "text": "दादा कहते थे: हम रूपकुंड के रास्ते वापस आए थे।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 306.52, "end": 307.45, "text": "वहाँ से नहीं।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 307.65, "end": 308.59, "text": "उसने सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 308.79, "end": 311.23, "text": "वो पत्थर रूपकुंड में नहीं था।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 311.23, "end": 314.35, "text": "वो बहुत ऊपर से आया था, बड़े पहाड़ से।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 314.35, "end": 318.72, "text": "बर्फ़ का पहाड़ टूटा, और उसे नीचे ग्लेशियर तक ले आया।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 318.72, "end": 321.16, "text": "वहाँ तक चरवाहे पहुँच सकते थे।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 321.16, "end": 323.86, "text": "वो लोग तीन दिन चले थे बर्फ़ में।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 323.86, "end": 328.23, "text": "और वापस आते वक़्त, रात को, रूपकुंड के पास रुक गए थे।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 328.23, "end": 328.49, "text": "बस।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 328.94, "end": 330.2, "text": "क्षितिज आगे झुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 330.4, "end": 331.55, "text": "और तीसरा चरवाहा?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 331.55, "end": 332.34, "text": "कुंदन सिंह?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 332.79, "end": 333.85, "text": "कुंदन चाचा?", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 334.05, "end": 335.97, "text": "हीरा लगभग मुस्कुरा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 336.17, "end": 338.36, "text": "उन्होंने बाद में शादी कर ली।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 338.36, "end": 339.62, "text": "कुमाऊँ में कहीं।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 339.62, "end": 344.17, "text": "दादा हमेशा एक ही बात कहते थे: कुंदन राजुला के देश चला गया,", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 344.17, "end": 345.73, "text": "और ठंडी चीज़ ले गया।", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 346.18, "end": 349.85, "text": "क्षितिज का पेन इतनी तेज़ चला, कि पेज फट गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 350.3, "end": 351.5, "text": "ठंडी चीज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 351.5, "end": 355.24, "text": "जो ठंडा रहा, उसे चरवाहा ले गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 355.24, "end": 356.92, "text": "राजुला के देश।", "who": "", "voice": "narrator", "diary": false}, {"start": 357.37, "end": 359.44, "text": "वो अब कोई पहेली नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.44, "end": 360.64, "text": "वो एक आदमी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 360.64, "end": 367.78, "text": "कुंदन सिंह नाम का एक असली आदमी, जिसने साठ साल पहले, कुमाऊँ के ऊँचे गाँवों में कहीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 367.78, "end": 372.25, "text": "एक परिवार में शादी की थी, और अपने साथ कुछ ले गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 372.7, "end": 375.43, "text": "ठीक तभी, सड़क पर इंजन ऊपर आए।", "who": "", "voice": "narrator", "diary": false}, {"start": 375.88, "end": 377.71, "text": "दो काली एस-यू-वीज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 377.71, "end": 381.28, "text": "पहली से रोहन उतरा, एक ऐसी जैकेट पहने,", "who": "", "voice": "narrator", "diary": false}, {"start": 381.28, "end": 384.08, "text": "जिसकी शायद अपनी एम्बेसी होगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 384.08, "end": 390.16, "text": "दूसरी से भल्ला उतरा, तीन और आदमियों, और सामान के एक ढेर के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 390.61, "end": 393.61, "text": "रोहन ने हमें हीरा की दहलीज़ पर देखा, और रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 393.61, "end": 396.61, "text": "एक सेकंड के लिए, उसके चेहरे ने कुछ भी नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 396.61, "end": 398.36, "text": "फिर वो मेरी तरफ़ मुस्कुराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 398.81, "end": 399.54, "text": "प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 399.54, "end": 401.56, "text": "आप तो हर जगह पहुँच जाते हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 402.01, "end": 404.94, "text": "उसने ये नहीं पूछा, कि हम वहाँ क्यों थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 404.94, "end": 406.37, "text": "उसे ज़रूरत नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 406.37, "end": 409.83, "text": "वो हीरा की तरफ़ मुड़ा, और बड़ी शराफ़त से बोला,", "who": "", "voice": "narrator", "diary": false}, {"start": 409.83, "end": 412.39, "text": "जैसे हम बाक़ी लोग वहाँ थे ही नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 412.84, "end": 413.31, "text": "हीरा जी।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 413.31, "end": 415.03, "text": "हम बीस मिनट में निकल रहे हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 415.23, "end": 418.41, "text": "फिर, हमारी तरफ़ एक नज़र डालते हुए:", "who": "", "voice": "narrator", "diary": false}, {"start": 418.61, "end": 421.7, "text": "आपके दोस्त भी साथ आ सकते हैं, अगर साथ चल पाएँ तो।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 422.15, "end": 423.93, "text": "वो एक न्योता था, उसी तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 423.93, "end": 426.93, "text": "जैसे किसी शेर की जम्हाई एक न्योता होती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 427.38, "end": 428.9, "text": "हीरा ने हमें देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 428.9, "end": 430.42, "text": "हमने हीरा को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 430.42, "end": 433.38, "text": "और शाओनी ने, मेरे कुछ कहने से पहले,", "who": "", "voice": "narrator", "diary": false}, {"start": 433.38, "end": 436.08, "text": "बहुत शांति से रोहन को जवाब दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 436.53, "end": 437.17, "text": "हम आ रहे हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 437.62, "end": 441.69, "text": "मैं उससे पूछना चाहता था, कि वो आख़िर सोच क्या रही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 441.69, "end": 445.15, "text": "मैंने नहीं पूछा, क्योंकि मुझे पहले से पता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 445.15, "end": 449.53, "text": "हीरा बर्फ़ में एक पहाड़ पर जा रहा था, एक ऐसे आदमी के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 449.53, "end": 453.15, "text": "जिसने मलेथा में एक इक्यानवे साल के बुज़ुर्ग को,", "who": "", "voice": "narrator", "diary": false}, {"start": 453.15, "end": 456.22, "text": "और अहमदाबाद में मेरी मम्मी को धमकाया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.22, "end": 458.76, "text": "हम उसे अकेले नहीं जाने दे रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 459.21, "end": 461.93, "text": "और मेरे दिमाग़ के किसी पिछले कोने में,", "who": "", "voice": "narrator", "diary": false}, {"start": 461.93, "end": 466.88, "text": "मुझे औली की बेंच पर बैठे रोहन की आवाज़ सुनाई देना बंद नहीं हो रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 466.88, "end": 469.24, "text": "मैं एक पोर्टर के साथ काम करता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 469.24, "end": 470.03, "text": "जवान लड़का।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.03, "end": 471.25, "text": "बर्फ़ पर कमाल का।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.75, "end": 480.49, "text": "रूपकुंड का ट्रेल, बाँज के जंगल से होते हुए, आली और बेदनी बुग्याल के मैदानों तक ऊपर जाता है: बहुत बड़े,", "who": "", "voice": "narrator", "diary": false}, {"start": 480.49, "end": 482.7, "text": "लहराते हुए, पतझड़ में सुनहरे,", "who": "", "voice": "narrator", "diary": false}, {"start": 482.7, "end": 485.66, "text": "और ऊपर त्रिशूल की पूरी दीवार चमकती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 485.66, "end": 488.09, "text": "गर्मियों में, मुझे बताया गया है,", "who": "", "voice": "narrator", "diary": false}, {"start": 488.09, "end": 492.49, "text": "ये हिंदुस्तान की सबसे ख़ूबसूरत पैदल यात्राओं में से एक है।", "who": "", "voice": "narrator", "diary": false}, {"start": 492.49, "end": 496.89, "text": "अक्टूबर के आख़िर में, बीस मीटर पीछे चलते रोहन सहगल के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 496.89, "end": 499.55, "text": "ये सबसे लंबी यात्राओं में से एक थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 500.0, "end": 503.87, "text": "ट्रेकिंग कंपनियाँ इसे तीन दिन की वॉक बताकर बेचती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 503.87, "end": 510.01, "text": "हमने इसे एक दिन में किया, क्योंकि रोहन पोर्टर्स को जल्दी करने के डबल पैसे दे रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 510.01, "end": 512.28, "text": "और कोई भी, मैं तो बिल्कुल नहीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 512.28, "end": 515.42, "text": "वो इंसान नहीं बनना चाहता था, जो आराम माँगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 515.87, "end": 518.34, "text": "हमने भगुवाबासा में कैंप लगाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 518.34, "end": 522.21, "text": "लगभग चार हज़ार मीटर पर, एक उजाड़, पथरीला गड्ढा।", "who": "", "voice": "narrator", "diary": false}, {"start": 522.21, "end": 528.46, "text": "अँधेरे में, रोहन के आदमियों ने अपने बड़े नारंगी टेंट्स चट्टानों के बीच लगाए,", "who": "", "voice": "narrator", "diary": false}, {"start": 528.46, "end": 534.06, "text": "और धीमी आवाज़ों में बातें करते रहे, और भल्ला पूरी रात बाहर बैठा रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 534.06, "end": 536.86, "text": "अँधेरे की तरफ़ मुँह किए, बिना सोए।", "who": "", "voice": "narrator", "diary": false}, {"start": 537.31, "end": 541.43, "text": "आधी रात के आसपास, रोहन के एक जवान आदमी ने, बोर होकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 541.43, "end": 546.02, "text": "स्टोव के पास एक धुन सीटी में बजानी शुरू की: एक पहाड़ी धुन,", "who": "", "voice": "narrator", "diary": false}, {"start": 546.02, "end": 548.23, "text": "वैसी, जो हर पोर्टर जानता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 548.23, "end": 552.11, "text": "तीसरे सुर से पहले ही भल्ला अपने पैरों पर खड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 552.11, "end": 553.45, "text": "वो चिल्लाया नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 553.45, "end": 557.65, "text": "उसने बस अपना एक भारी हाथ उस जवान आदमी के कंधे पर रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 557.65, "end": 558.83, "text": "और धीरे से कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 559.03, "end": 559.59, "text": "यहाँ नहीं।", "who": "भल्ला", "voice": "bhalla", "diary": false}, {"start": 560.04, "end": 561.54, "text": "जवान आदमी रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.54, "end": 566.38, "text": "भल्ला वापस बैठ गया, और उत्तर की तरफ़ अँधेरे में घूरता रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 566.38, "end": 570.04, "text": "जहाँ बड़े पहाड़ थे, और भोर तक फिर हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 570.49, "end": 574.55, "text": "क्षितिज अपने स्लीपिंग बैग के किनारे से उसे देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 574.55, "end": 575.98, "text": "टॉर्च की रोशनी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 575.98, "end": 580.57, "text": "मैंने उसे लिखते देखा: भल्ला इस पहाड़ पर किसी चीज़ से डरता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 580.57, "end": 581.77, "text": "हमसे भी ज़्यादा।", "who": "", "voice": "narrator", "diary": false}, {"start": 581.77, "end": 583.28, "text": "यहाँ नहीं, ऐसे नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 583.28, "end": 583.65, "text": "यहाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 583.65, "end": 585.76, "text": "क्या वो पहले यहाँ आ चुका है?", "who": "", "voice": "narrator", "diary": false}, {"start": 587.26, "end": 591.05, "text": "हम सुबह चार बजे फिर निकले, टॉर्च की रोशनी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 591.05, "end": 595.02, "text": "झील की तरफ़ एक खड़ी, बर्फ़ीली ज़िगज़ैग चढ़ाई पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 595.47, "end": 597.86, "text": "मैंने रूपकुंड के बारे में पढ़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 597.86, "end": 599.49, "text": "हर उस इंसान ने पढ़ा है,", "who": "", "voice": "narrator", "diary": false}, {"start": 599.49, "end": 603.79, "text": "जिसने कभी गूगल पर मिस्टीरियस प्लेसेज़ इन इंडिया सर्च किया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 603.79, "end": 610.7, "text": "लेकिन कोई भी चीज़ आपको उस पल के लिए तैयार नहीं करती, जब आप सच में भोर में किनारे पर खड़े होते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 610.7, "end": 613.23, "text": "पाँच हज़ार मीटर से ज़्यादा ऊँचाई पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 613.23, "end": 616.69, "text": "फेफड़ों में टूटे काँच भरे हुए, और नीचे देखते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 617.14, "end": 618.11, "text": "वो छोटी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 618.11, "end": 619.52, "text": "ये पहला झटका है।", "who": "", "voice": "narrator", "diary": false}, {"start": 619.52, "end": 624.73, "text": "कोई बड़ी झील नहीं: पानी का एक गोल, गहरा कटोरा, आधा जमा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 624.73, "end": 629.15, "text": "चारों तरफ़ से कंकड़-पत्थर और पुरानी बर्फ़ से घिरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 629.15, "end": 633.74, "text": "जुनारगली की धार के नीचे, पहाड़ की हथेली में रखा हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 634.19, "end": 639.6, "text": "और उसके किनारों पर, पत्थरों के बीच, बर्फ़ में आधी दबी हुई, कुछ फीकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 639.6, "end": 644.28, "text": "सफ़ेद शक्लें हैं, जिनके बारे में आपको धीरे-धीरे समझ आता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 644.28, "end": 645.79, "text": "कि वो हड्डियाँ हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 646.24, "end": 648.14, "text": "यहाँ सैकड़ों लोग मरे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 648.14, "end": 649.8, "text": "जब से किसी को याद है,", "who": "", "voice": "narrator", "diary": false}, {"start": 649.8, "end": 653.51, "text": "उनके अवशेष इस झील के चारों तरफ़ बिखरे पड़े हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 653.51, "end": 656.99, "text": "दशकों तक, किसी को नहीं पता था, कि वो कौन थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 656.99, "end": 663.07, "text": "फिर, दो हज़ार उन्नीस में, वैज्ञानिकों ने, नेचर कम्युनिकेशंस नाम के जर्नल में,", "who": "", "voice": "narrator", "diary": false}, {"start": 663.07, "end": 668.84, "text": "अड़तीस कंकालों पर एक लंबी डी-एन-ए स्टडी के नतीजे छापे: हिंदुस्तान से छपी,", "who": "", "voice": "narrator", "diary": false}, {"start": 668.84, "end": 672.31, "text": "सबसे पहली प्राचीन डी-एन-ए स्टडीज़ में से एक।", "who": "", "voice": "narrator", "diary": false}, {"start": 672.76, "end": 678.17, "text": "ये कंकाल किसी एक ग्रुप के नहीं थे, जो एक ही हादसे में मरा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 678.17, "end": 681.53, "text": "वो कम से कम तीन अलग-अलग ग्रुप्स के थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 681.53, "end": 686.93, "text": "जो यहाँ अलग-अलग वक़्त पर मरे, लगभग एक हज़ार साल के फ़ासले पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 686.93, "end": 690.56, "text": "ज़्यादातर की वंशावली, साउथ एशिया जैसी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 690.56, "end": 696.41, "text": "लेकिन चौदह लोगों के एक ग्रुप की वंशावली, पूर्वी भूमध्य सागर से थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 696.41, "end": 700.92, "text": "ग्रीस और क्रीट के लोगों से बहुत क़रीब से जुड़ी हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 700.92, "end": 704.55, "text": "और वो यहाँ लगभग अठारह सौ के आसपास मरे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.0, "end": 705.83, "text": "ग्रीक लोग।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.83, "end": 709.99, "text": "गढ़वाल हिमालय में, पाँच हज़ार मीटर ऊपर, एक झील पर।", "who": "", "voice": "narrator", "diary": false}, {"start": 709.99, "end": 712.57, "text": "कोई नहीं जानता, वो क्यों आए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 712.57, "end": 714.9, "text": "कोई नहीं जानता, वो कैसे मरे।", "who": "", "voice": "narrator", "diary": false}, {"start": 715.35, "end": 718.07, "text": "हीरा ने, मेरे बग़ल में खड़े होकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 718.07, "end": 722.35, "text": "मुझे घाटी का जवाब बताया, जो डी-एन-ए से भी पुराना है।", "who": "", "voice": "narrator", "diary": false}, {"start": 722.35, "end": 726.71, "text": "रूपकुंड, नंदा देवी राज जात के रास्ते पर है, उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 726.71, "end": 732.96, "text": "बहुत पहले, एक राजा एक शानदार दल के साथ यात्रा पर निकला था, नौकर, बजाने वाले,", "who": "", "voice": "narrator", "diary": false}, {"start": 732.96, "end": 737.0, "text": "नाचने वाले, और उन्होंने देवी के पवित्र रास्ते पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 737.0, "end": 738.56, "text": "उसके नियम तोड़ दिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 738.56, "end": 743.91, "text": "नंदा का ग़ुस्सा ओलों के तूफ़ान बनकर उन पर गिरा, और वो यहीं मर गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 743.91, "end": 748.6, "text": "इसी झील के किनारे, और उनकी हड्डियाँ कभी यहाँ से गईं नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 749.05, "end": 751.89, "text": "मैंने वही किया, जो मैं करता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 751.89, "end": 753.31, "text": "मैंने हाथ जोड़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 753.31, "end": 754.56, "text": "एक तरफ़ साइंस।", "who": "", "voice": "narrator", "diary": false}, {"start": 754.56, "end": 756.07, "text": "दूसरी तरफ़ कहानी।", "who": "", "voice": "narrator", "diary": false}, {"start": 756.07, "end": 762.37, "text": "और बीच में अजनबियों से भरी एक झील, जो धरती के कोनों से चलकर, बर्फ़ में,", "who": "", "voice": "narrator", "diary": false}, {"start": 762.37, "end": 767.79, "text": "एक ऐसी जगह मरने आए थे, जहाँ होने की उनके पास कोई वजह नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 769.29, "end": 771.01, "text": "मेरा फ़ोन बज़ हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 771.01, "end": 772.35, "text": "एक बार सिग्नल।", "who": "", "voice": "narrator", "diary": false}, {"start": 772.35, "end": 773.31, "text": "ज़ाहिर है।", "who": "", "voice": "narrator", "diary": false}, {"start": 773.31, "end": 775.52, "text": "ज़ाहिर है, यही होना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 776.22, "end": 776.59, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 777.29, "end": 779.1, "text": "पहुँच गए मौसी के घर।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 779.3, "end": 780.49, "text": "उन्होंने मुझे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 780.69, "end": 781.44, "text": "तुम कहाँ हो?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 781.89, "end": 783.0, "text": "एक झील पे, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 783.45, "end": 784.01, "text": "अच्छा है।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 784.01, "end": 784.81, "text": "कुछ गरम खाया?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 785.51, "end": 786.86, "text": "मैंने नीचे हड्डियों को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 787.56, "end": 788.33, "text": "नहीं, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 788.53, "end": 789.08, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 789.28, "end": 790.56, "text": "हड्डियाँ गिन रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 791.26, "end": 793.23, "text": "वडोदरा से एक लंबा पॉज़ आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 793.93, "end": 794.53, "text": "पार्थ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 794.73, "end": 795.68, "text": "मेरी मम्मी ने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 795.88, "end": 796.8, "text": "तुम घर आओ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 796.8, "end": 798.2, "text": "फिर बात करेंगे।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 799.7, "end": 805.11, "text": "रोहन के आदमी अपनी रडार मशीन को एक स्लेज पर घसीटकर ऊपर लाए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 805.11, "end": 812.03, "text": "दो घंटे तक, वो उसे झील के किनारे पर चलाते रहे, कंकड़-पत्थरों के पार, आगे-पीछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 812.03, "end": 814.78, "text": "और रोहन एक चट्टान पर खड़ा होकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 814.78, "end": 818.16, "text": "एक मज़बूत टैबलेट की स्क्रीन देखता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 818.61, "end": 819.68, "text": "कुछ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 819.68, "end": 820.51, "text": "चट्टान।", "who": "", "voice": "narrator", "diary": false}, {"start": 820.51, "end": 821.23, "text": "बर्फ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 821.23, "end": 821.94, "text": "हड्डी।", "who": "", "voice": "narrator", "diary": false}, {"start": 822.39, "end": 824.91, "text": "मैंने वो पल देखा, जब उसे समझ आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 824.91, "end": 826.21, "text": "वो चिल्लाया नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 826.21, "end": 827.59, "text": "उसने गाली नहीं दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 827.59, "end": 831.1, "text": "उसने बस टैबलेट नीचे किया, और झील को देखते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 831.1, "end": 832.86, "text": "बिल्कुल स्थिर खड़ा रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 833.31, "end": 835.56, "text": "फिर वो मुड़ा, और क्षितिज को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 836.01, "end": 836.78, "text": "मुझे नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 836.78, "end": 837.85, "text": "शाओनी को नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 837.85, "end": 840.61, "text": "क्षितिज को: डायरी वाला वो चुप लड़का,", "who": "", "voice": "narrator", "diary": false}, {"start": 840.61, "end": 843.3, "text": "जिसने पूरी सुबह लिखते हुए बिताई थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 843.3, "end": 845.76, "text": "और एक बार भी हैरान नहीं दिखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 846.21, "end": 847.82, "text": "मुर्दों की झील।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 848.02, "end": 850.18, "text": "रोहन ने धीरे से, उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 850.38, "end": 851.18, "text": "हड्डियाँ गिन ले।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 851.38, "end": 852.57, "text": "वो लगभग हँस दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 852.77, "end": 853.4, "text": "अच्छा है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 853.4, "end": 854.5, "text": "सच में अच्छा है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 854.5, "end": 855.95, "text": "तुमने लिखा था ना, ये?", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 856.4, "end": 858.36, "text": "क्षितिज ने जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 858.36, "end": 860.24, "text": "लेकिन उसके कान लाल हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 860.69, "end": 861.74, "text": "होशियार लड़का।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 861.94, "end": 863.0, "text": "रोहन ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 863.0, "end": 867.63, "text": "पहली बार, उसकी आवाज़ में बिल्कुल भी गर्माहट नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 867.63, "end": 869.94, "text": "उसने हमारी तरफ़ पीठ कर ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.14, "end": 870.59, "text": "भल्ला।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 870.59, "end": 872.0, "text": "हम नीचे चल रहे हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 873.5, "end": 880.22, "text": "रूपकुंड से भगुवाबासा तक का नीचे का रास्ता, ढीली चट्टानों की एक दीवार के नीचे, एक लंबी,", "who": "", "voice": "narrator", "diary": false}, {"start": 880.22, "end": 883.42, "text": "खड़ी ढलान को पार करता है: उस तरह की ढलान,", "who": "", "voice": "narrator", "diary": false}, {"start": 883.42, "end": 887.8, "text": "जहाँ पत्थरों को सिर्फ़ ठंड ने अपनी जगह पकड़ रखा होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 888.25, "end": 890.56, "text": "तब तक, उस पर पूरी धूप आ चुकी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 891.01, "end": 893.39, "text": "हम एक लाइन में फैले हुए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 893.39, "end": 896.57, "text": "सबसे आगे हीरा, फिर मैं, फिर क्षितिज।", "who": "", "voice": "narrator", "diary": false}, {"start": 896.57, "end": 900.2, "text": "शाओनी थोड़ा पीछे, भल्ला पर नज़र रखते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 900.2, "end": 903.2, "text": "जो पीछे रहकर उसके पास चलने लगा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 903.2, "end": 906.21, "text": "रोहन और उसके आदमी, हम सबसे आगे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 906.66, "end": 910.15, "text": "मैंने उसे देखने से पहले सुना: ऊपर बहुत ऊँचाई पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 910.15, "end": 912.48, "text": "एक सूखी आवाज़, जैसे गोली चली हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 912.48, "end": 913.43, "text": "फिर एक आवाज़,", "who": "", "voice": "narrator", "diary": false}, {"start": 913.43, "end": 917.22, "text": "जैसे किसी दैत्य की बाल्टी में बजरी उड़ेली जा रही हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 917.67, "end": 920.35, "text": "हीरा घूमा, और हम सब पर चीख़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 920.55, "end": 921.17, "text": "भागो!", "who": "हीरा", "voice": "hira", "diary": false}, {"start": 921.62, "end": 924.51, "text": "मैंने क्षितिज की जैकेट पकड़ी, और भागा।", "who": "", "voice": "narrator", "diary": false}, {"start": 924.51, "end": 928.02, "text": "पत्थर मेरे बग़ल से निकले: पहले छोटे, फिर बड़े,", "who": "", "voice": "narrator", "diary": false}, {"start": 928.02, "end": 931.75, "text": "उछलते, घूमते, और हमारे पीछे रास्ते पर टकराते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 931.75, "end": 937.24, "text": "प्रेशर कुकर जितनी बड़ी एक चट्टान, मेरे पैर से एक मीटर दूर ज़मीन पर गिरी,", "who": "", "voice": "narrator", "diary": false}, {"start": 937.24, "end": 940.59, "text": "और मेरे सिर के ऊपर से उछलकर घाटी में चली गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 940.59, "end": 941.5, "text": "हर तरफ़ धूल।", "who": "", "voice": "narrator", "diary": false}, {"start": 941.5, "end": 943.26, "text": "मैं देख नहीं पा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 943.26, "end": 945.01, "text": "साँस नहीं ले पा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 945.01, "end": 950.19, "text": "मैं बस क्षितिज को पकड़े भागता रहा, जब तक हीरा ने हम दोनों को पकड़कर,", "who": "", "voice": "narrator", "diary": false}, {"start": 950.19, "end": 953.39, "text": "एक बड़े पत्थर के पीछे नीचे नहीं खींच लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 953.84, "end": 956.94, "text": "और फिर, धीरे-धीरे, वो रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 957.64, "end": 959.64, "text": "धूल हवा के साथ उड़ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 960.34, "end": 965.37, "text": "जहाँ हमारे पीछे रास्ता था, वहाँ अब टूटी चट्टानों की एक कच्ची,", "who": "", "voice": "narrator", "diary": false}, {"start": 965.37, "end": 970.31, "text": "ताज़ा ढलान थी, अभी भी खिसकती हुई, अभी भी खटकती और बैठती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 970.31, "end": 974.51, "text": "उसने ट्रेल को साफ़-साफ़ दो हिस्सों में काट दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.96, "end": 976.33, "text": "हमारी तरफ़: हीरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 976.33, "end": 976.65, "text": "मैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 976.65, "end": 977.3, "text": "क्षितिज।", "who": "", "voice": "narrator", "diary": false}, {"start": 977.75, "end": 980.93, "text": "दूसरी तरफ़, स्लाइड के पार, चालीस मीटर दूर,", "who": "", "voice": "narrator", "diary": false}, {"start": 980.93, "end": 985.25, "text": "ट्रेल पर दो आकृतियाँ अकेली खड़ी थीं, ग्रे धूल से ढकी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 985.95, "end": 987.07, "text": "शाओनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 987.77, "end": 988.79, "text": "और भल्ला।", "who": "", "voice": "narrator", "diary": false}, {"start": 989.49, "end": 991.5, "text": "उसने पार हमारी तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 991.5, "end": 993.99, "text": "उसने एक हाथ उठाया: मैं ठीक हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 993.99, "end": 1000.01, "text": "फिर वो मुड़ी, और अपने बग़ल में खड़े उस बड़े आदमी को देखा, और उसने उसे देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1000.01, "end": 1003.95, "text": "और उनके और हमारे बीच, चालीस मीटर की वो चट्टान थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1003.95, "end": 1006.92, "text": "जिसे धरती पर कोई पार नहीं कर सकता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1007.37, "end": 1012.56, "text": "ऊपर से, ढलान पर नीचे, रोहन की आवाज़ आई, हमेशा की तरह शांत।", "who": "", "voice": "narrator", "diary": false}, {"start": 1013.01, "end": 1013.4, "text": "भल्ला!", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1013.4, "end": 1014.5, "text": "लड़की के साथ रहो।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1014.5, "end": 1015.67, "text": "हम नीचे मिलते हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1016.12, "end": 1018.44, "text": "सूरज एक बादल के पीछे चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1018.44, "end": 1021.8, "text": "और शाओनी, हमारी तरफ़ एक और नज़र डाले बिना,", "who": "", "voice": "narrator", "diary": false}, {"start": 1021.8, "end": 1026.84, "text": "पहाड़ के दूसरी तरफ़ नीचे चलने लगी, और भल्ला, उसके एक क़दम पीछे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1027.29, "end": 1028.8, "text": "क्षितिज हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1028.8, "end": 1034.65, "text": "वो अपनी डायरी को सीने से लगाए वहीं खड़ा रहा, और अपनी बहन को देखता रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.65, "end": 1038.83, "text": "जब तक वो इतनी छोटी नहीं हो गई, कि दिखना बंद हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1039.28, "end": 1041.24, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1041.24, "end": 1044.39, "text": "डेज़ एट टू नाइन, वान और रूपकुंड।", "who": "", "voice": "narrator", "diary": true}, {"start": 1044.84, "end": 1048.53, "text": "झूठे वर्स ने आर. को एक असली सुराग़ तक भेज दिया: हीरा,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1048.53, "end": 1050.76, "text": "भवान सिंह का पोता, दूसरा चरवाहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1050.76, "end": 1051.53, "text": "मेरी ग़लती।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1051.53, "end": 1053.76, "text": "मैंने नोटबुक ध्यान से नहीं पढ़ी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1053.76, "end": 1054.94, "text": "दोबारा नहीं होगा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1054.94, "end": 1056.33, "text": "दीदी कहती है, हमारी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1056.33, "end": 1058.14, "text": "दीदी ग़लत है, पर प्यार से।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1058.59, "end": 1062.86, "text": "हीरा के दादा: हम रूपकुंड के रास्ते वापस आए थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1062.86, "end": 1064.35, "text": "वो वहाँ नहीं था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1064.35, "end": 1067.6, "text": "पत्थर और ऊपर था, बड़े पहाड़ के पास।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1067.6, "end": 1069.27, "text": "बर्फ़ में तीन दिन।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1069.72, "end": 1072.03, "text": "कुंदन सिंह, तीसरा चरवाहा,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1072.03, "end": 1077.59, "text": "राजुला के देश में एक परिवार में ब्याहा, और ठंडी चीज़ ले गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1077.59, "end": 1080.75, "text": "तो ठंडी चीज़ नंदा देवी पर नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1080.75, "end": 1083.43, "text": "वो कुमाऊँ में किसी घर में है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1083.43, "end": 1083.9, "text": "कहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1084.35, "end": 1088.17, "text": "रूपकुंड: मुर्दों के तीन ग्रुप, एक हज़ार साल के फ़ासले पर।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1088.17, "end": 1089.58, "text": "कोई नहीं जानता क्यों।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1089.58, "end": 1091.13, "text": "पार्थ भाई ने हाथ जोड़े।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1091.13, "end": 1091.73, "text": "मैंने भी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1092.18, "end": 1094.9, "text": "भगुवाबासा में भल्ला: यहाँ नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1094.9, "end": 1096.93, "text": "एक सीटी, एक पहाड़ी धुन।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1096.93, "end": 1099.74, "text": "उसने तीन सुरों में उसे रोक दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1100.19, "end": 1102.91, "text": "आर. को पता है, कि झूठा वर्स मैंने लिखा था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1102.91, "end": 1104.46, "text": "उसने कहा, होशियार लड़का।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1104.46, "end": 1106.14, "text": "उसने ये प्यार से नहीं कहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1106.59, "end": 1109.34, "text": "दीदी पत्थरों की स्लाइड के दूसरी तरफ़ है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1109.34, "end": 1110.24, "text": "भल्ला के साथ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1110.24, "end": 1111.96, "text": "उसने हाथ उठाया, और चल दी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1111.96, "end": 1113.74, "text": "वो तीलू रौतेली की तरह चली।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1113.74, "end": 1115.53, "text": "मैं बहुत कोशिश कर रहा हूँ,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1115.53, "end": 1118.69, "text": "कि एक डिटेक्टिव की तरह लिखूँ, भाई की तरह नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 20.18, "bed": "caper"}, {"at": 72.02, "bed": "suspicion"}, {"at": 157.83, "bed": "tender"}, {"at": 205.41, "bed": "roadnight"}, {"at": 230.68, "bed": "village"}, {"at": 294.33, "bed": "legend"}, {"at": 327.74, "bed": "discovery"}, {"at": 371.5, "bed": "threat"}, {"at": 471.55, "bed": "trek"}, {"at": 514.67, "bed": "vigil"}, {"at": 586.06, "bed": "cold"}, {"at": 615.94, "bed": "roopkund"}, {"at": 645.04, "bed": "docu"}, {"at": 714.15, "bed": "lore"}, {"at": 747.85, "bed": "roopkund"}, {"at": 768.09, "bed": "receipt"}, {"at": 798.5, "bed": "suspense"}, {"at": 821.19, "bed": "threat"}, {"at": 872.3, "bed": "tension"}, {"at": 905.46, "bed": "rockfall"}, {"at": 952.64, "bed": "stillness"}, {"at": 988.29, "bed": "sinking"}, {"at": 1038.08, "bed": "diary"}, {"at": 1038.08, "bed": "diary"}], "hits": [{"at": 21.23, "fx": "phonering"}, {"at": 106.69, "fx": "page"}, {"at": 118.18, "fx": "sting"}, {"at": 202.56, "fx": "carstart"}, {"at": 246.5, "fx": "sting_light"}, {"at": 346.03, "fx": "sting"}, {"at": 372.55, "fx": "suv"}, {"at": 537.16, "fx": "whistle"}, {"at": 704.85, "fx": "sting"}, {"at": 769.14, "fx": "ping"}, {"at": 860.54, "fx": "sting"}, {"at": 906.51, "fx": "rockfall"}, {"at": 987.62, "fx": "sting"}, {"at": 1100.04, "fx": "sting_light"}, {"at": 1106.44, "fx": "sting"}], "next": {"label": "एपिसोड 9", "en": "The Night the Drums Woke the Gods", "hook": "एक रात, ढोल, और एक देवता, जो एक किसान के शरीर में उतरता है।"}};
